CREATE TABLE topic(id INTEGER PRIMARY KEY, name TEXT, track TEXT, level INT, difficulty INT, hours INT, unlocks INT, ord INT);
CREATE TABLE level(n INTEGER PRIMARY KEY, title TEXT, explanation TEXT, question TEXT, answer TEXT);
CREATE TABLE prereq(topic_id INT, requires_id INT);
CREATE TABLE progress(topic_id INT PRIMARY KEY, mastered_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE VIEW next_up AS SELECT * FROM topic WHERE id NOT IN (SELECT topic_id FROM progress) AND NOT EXISTS (SELECT 1 FROM prereq p WHERE p.topic_id = topic.id AND p.requires_id NOT IN (SELECT topic_id FROM progress)) ORDER BY level, unlocks DESC, difficulty;
